package net.officefloor.hq.app;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A task the user keeps on a project: a title and a {@code done} flag that can be ticked off, plus
 * the id of the {@link Project} it belongs to. Mapped to the {@code task} table created by
 * {@code V14__tasks.sql}. IDENTITY id so the DB assigns it on insert (seed inserts explicit ids via
 * JdbcTemplate; GENERATED BY DEFAULT allows both).
 */
@Entity
@Table(name = "task")
public class Task {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id")
    private Long projectId;

