  const create = useMutation({
    mutationFn: () =>
      postJson<Note>('/api/notes', { targetType: 'project', targetId: projectId, text }),
    onSuccess: () => {
      setText('');
      void queryClient.invalidateQueries({ queryKey: ['notes'] });
    },
  });

